public Set getAllowedValues()
{
    var ret = new Set(Types::Int64);

    EcoResProductMasterModelingPolicy modelingPolicy;

    while select ProductMaster from modelingPolicy
    {
        if (!ret.in(modelingPolicy.ProductMaster))
        {
            ret.add(modelingPolicy.ProductMaster);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(EcoResProductMasterModelingPolicy, ProductMaster));
    qbr.value(queryValue(_value));
}
